package checkpoint

import (
	"context"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/redact"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/stretchr/testify/require"
)

func TestReproSequentialBackfillsHaveNoTotalDeadline(t *testing.T) {
	t.Parallel()

	seed := newRefsStore(t)
	checkpointIDs := make([]id.CheckpointID, 3)
	refHashes := make(map[plumbing.ReferenceName]plumbing.Hash, len(checkpointIDs))
	for index := range checkpointIDs {
		checkpointID, err := id.GenerateULID()
		require.NoError(t, err)
		checkpointIDs[index] = checkpointID
		refsWrite(t, seed, checkpointID, "slow-finalize", "provisional transcript")

		refName, err := RefName(checkpointID)
		require.NoError(t, err)
		ref, err := seed.repo.Reference(refName, true)
		require.NoError(t, err)
		refHashes[refName] = ref.Hash()
		require.NoError(t, seed.repo.Storer.RemoveReference(refName))
	}

	store := newGitRefsStore(seed.repo)
	store.SetRefFetcher(func(ctx context.Context, refName plumbing.ReferenceName) error {
		timer := time.NewTimer(15 * time.Millisecond)
		defer timer.Stop()
		select {
		case <-timer.C:
			return seed.repo.Storer.SetReference(plumbing.NewHashReference(refName, refHashes[refName]))
		case <-ctx.Done():
			return ctx.Err()
		}
	})

	started := time.Now()
	for _, checkpointID := range checkpointIDs {
		require.NoError(t, store.Write(context.Background(), SessionTranscript(UpdateOptions{
			CheckpointID: checkpointID,
			SessionID:    "slow-finalize",
			Transcript:   redact.AlreadyRedacted([]byte("full transcript")),
		})))
	}
	elapsed := time.Since(started)
	t.Logf("elapsed=%s", elapsed)

	require.Less(t, elapsed, 35*time.Millisecond,
		"the whole finalize-shaped pass must stop near its total budget, not pay one near-budget fetch per checkpoint")
}

